def complete(store, lesson, request_id):
    if not isinstance(lesson, str) or not lesson or not isinstance(request_id, str) or not request_id:
        return {'status': 400, 'error': 'required text is missing'}
    old = store['requests'].get(request_id)
    if old is not None:
        if old['lesson'] != lesson:
            return {'status': 409, 'error': 'request ID already has different content'}
        return old['result']
    result = {'status': 201, 'lesson': lesson}
    store['requests'][request_id] = {'lesson': lesson, 'result': result}
    store['completed'].add(lesson)
    return result

store = {'requests': {}, 'completed': set()}
print(complete(store, 'loops', 'r-1'))
print(complete(store, 'loops', 'r-1'))
print(complete(store, 'files', 'r-1'))
print(store['completed'])
